for (let r = 2; r <= 7; r++) {
  const f = (x: string) => `COUNTIFS($A$2:$A${r},"${x}",$B$2:$B${r},FALSE)>0`;
  s.getRange(`C${r}`).setValue(`=IF(${f('Potato')},"Worst",IF(${f('Tomato')},"Ignore",IF(${f('Pickle')},"Bad","Good")))`);
}
const out = [];
